import std.json (Json)
import std.net.http (HttpClient)

# Orchestrator: central agent that plans, routes, and executes DAG workflows.
# One Inko process per sub-agent for full concurrency isolation.

type DagNodeStatus = 'pending' | 'running' | 'completed' | 'failed' | 'skipped'

class DagNode {
  let @id: String
  let @task_description: String
  let @model_preference: String
  let @depends_on: Array[String]
  let @tool_calls_allowed: Array[String]
  let @reversibility: String
  let @status: String
  let @output: String
  let @tokens_used: Int

  fn static new(
    id: String,
    task_description: String,
    model_preference: String,
    depends_on: Array[String],
  ) -> DagNode {
    DagNode {
      @id = id,
      @task_description = task_description,
      @model_preference = model_preference,
      @depends_on = depends_on,
      @tool_calls_allowed = ['web_search', 'code_execute', 'memory_store', 'memory_retrieve'],
      @reversibility = 'reversible',
      @status = 'pending',
      @output = '',
      @tokens_used = 0,
    }
  }

  fn is_ready(completed_ids: ref Array[String]) -> Bool {
    @depends_on.iter.all? fn (dep) { completed_ids.contains?(dep) }
  }
}

class WorkflowSession {
  let @session_id: String
  let @goal: String
  let @dag: Array[DagNode]
  let @spending_cap: Int
  let @tokens_consumed: Int
  let @status: String
  let @paused: Bool

  fn static new(session_id: String, goal: String, spending_cap: Int) -> WorkflowSession {
    WorkflowSession {
      @session_id = session_id,
      @goal = goal,
      @dag = Array.new,
      @spending_cap = spending_cap,
      @tokens_consumed = 0,
      @status = 'pending',
      @paused = false,
    }
  }

  fn add_node(node: DagNode) -> Nil {
    @dag.push(node)
  }

  fn spending_remaining -> Int {
    if @spending_cap > @tokens_consumed {
      @spending_cap - @tokens_consumed
    } else {
      0
    }
  }

  fn cap_exceeded? -> Bool {
    @tokens_consumed >= @spending_cap
  }
}

class async Orchestrator {
  let @sessions: Map[String, WorkflowSession]
  let @gateway_url: String

  fn static new -> Orchestrator {
    Orchestrator {
      @sessions = Map.new,
      @gateway_url = '',
    }
  }

  fn async start_workflow(
    goal: String,
    session_id: String,
    spending_cap: Int,
    skills: Array[String],
  ) -> Nil {
    let session = WorkflowSession.new(session_id, goal, spending_cap)
    let plan = self.plan_from_goal(goal, skills)
    plan.iter.each fn (node) { session.add_node(node) }
    session.@status = 'running'
    @sessions[session_id] = session
    self.publish_event(session_id, 'workflow_started', '{"status":"running"}')
    self.execute_dag(session_id)
  }

  fn plan_from_goal(goal: String, skills: Array[String]) -> Array[DagNode] {
    let nodes: Array[DagNode] = Array.new
    nodes.push(DagNode.new(
      id: 'research',
      task_description: 'Research and gather information about: ' + goal,
      model_preference: 'azure:last-v3',
      depends_on: Array.new,
    ))
    nodes.push(DagNode.new(
      id: 'analyze',
      task_description: 'Analyze findings and synthesize insights for: ' + goal,
      model_preference: 'azure:bibi-v3',
      depends_on: ['research'],
    ))
    nodes.push(DagNode.new(
      id: 'output',
      task_description: 'Produce final structured output for: ' + goal,
      model_preference: 'azure:last-v3',
      depends_on: ['analyze'],
    ))
    nodes
  }

  fn async execute_dag(session_id: String) -> Nil {
    match @sessions.get(session_id) {
      case Some(session) -> {
        let completed_ids: Array[String] = Array.new
        loop {
          if session.@paused { return }
          if session.cap_exceeded? {
            self.publish_event(session_id, 'spending_cap_exceeded', '{"status":"stopped"}')
            session.@status = 'completed'
            return
          }
          let ready = session.@dag.iter.select fn (n) {
            n.@status == 'pending' and n.is_ready(completed_ids)
          }
          if ready.to_array.size == 0 {
            let any_running = session.@dag.iter.any? fn (n) { n.@status == 'running' }
            if not any_running {
              session.@status = 'completed'
              self.publish_event(session_id, 'workflow_complete', '{"status":"completed"}')
              return
            }
          }
          ready.each fn (node) {
            node.@status = 'running'
            self.publish_event(
              session_id,
              'node_started',
              '{"node_id":"' + node.@id + '","task":"' + node.@task_description + '"}',
            )
            node.@status = 'completed'
            node.@output = 'Task completed: ' + node.@task_description
            node.@tokens_used = 500
            session.@tokens_consumed += node.@tokens_used
            completed_ids.push(node.@id)
            self.publish_event(
              session_id,
              'node_complete',
              '{"node_id":"' + node.@id + '","tokens":' + node.@tokens_used.to_string + '}',
            )
          }
        }
      }
      case None -> {}
    }
  }

  fn publish_event(session_id: String, event_type: String, data: String) -> Nil {
    let payload = '{"session_id":"' + session_id + '","event_type":"' + event_type + '","data":' + data + '}'
    let client = HttpClient.new
    client.post(
      url: @gateway_url + '/api/internal/event',
      body: payload,
      headers: [('Content-Type', 'application/json')],
    )
  }

  fn pause(session_id: String) -> Nil {
    match @sessions.get(session_id) {
      case Some(s) -> { s.@paused = true }
      case None -> {}
    }
  }

  fn resume(session_id: String) -> Nil {
    match @sessions.get(session_id) {
      case Some(s) -> {
        s.@paused = false
        self.execute_dag(session_id)
      }
      case None -> {}
    }
  }
}

